import * as T from 'three';
import {targets102,LABELS102} from './maintenance-session102.js?v=156';
import {actionObject123} from './meter-leads123.js?v=194';
import {createGlove104} from './repair-glove104.js?v=199';
import {InteractionHand117} from './interaction-hand117.js?v=199';
const text=(node,value)=>{if(node.textContent!==value)node.textContent=value;};
// The workshop uses the same aimed, near-field work and carry loop as the substation.
export class WorkshopPlay199{
 constructor(view){this.view=view;const d=view.canvas.ownerDocument||document;this.doc=d;this.guide=d.createElement('div');this.guide.className='carry189-guide';this.guide.hidden=true;this.guide.innerHTML='<span data-guide189-arrow>◇</span><small data-guide189-label></small>';view.canvas.parentElement.append(this.guide);this.progress=d.createElement('progress');this.progress.className='work199-progress';this.progress.max=1;this.progress.hidden=true;this.progress.setAttribute('aria-label','Avance del trabajo');view.canvas.parentElement.append(this.progress);d.addEventListener('keyup',e=>{if(e.key?.toLowerCase()==='e')this.end();});globalThis.addEventListener?.('blur',()=>this.end());}
 active(){const v=this.view;return !!v.state&&v.rig?.id===v.state.id&&!v.pendingRig103&&this.doc.body.dataset.loading142!=='true'&&!v.state.complete&&v.walk176?.active()&&!v.walk176.inspecting196&&!v.walk176.help181?.open&&!v.walk176.bagActive()&&!globalThis.window?.metroMission117?.journal196;}
 get held(){return this.carried;}
 message(value){this.view.h.miss(value);}
 event(){const r=this.view.canvas.getBoundingClientRect();return{clientX:r.left+r.width/2,clientY:r.top+r.height/2};}
 aimed(){const v=this.view,expected=targets102(v.state),hit=v.state.selectedItem?v.dropTarget(this.event()):(v.pick(this.event(),expected)||v.pick(this.event()));if(!hit)return null;let id=hit.id;if(/^doorSlide/.test(id))id=expected.find(k=>k==='openTest'||k==='closeTest')||id;if(['wheelHub','newWheel'].includes(id)&&expected.includes('rotateTest'))id='rotateTest';if(id==='meter'&&expected.includes('clearProbes'))id='clearProbes';return{...hit,id};}
 begin(){const v=this.view;if(!this.active()||v.drag)return false;const hit=this.aimed();if(!hit||!targets102(v.state).includes(hit.id)||!v.canReach190(hit)){this.message('Acércate y apunta a la pieza indicada. Ctrl: agacharte · Tab: bolsa.');return false;}
  const tool=/^screw/.test(hit.id)?'screwdriver':/^bolt/.test(hit.id)?'wrench':['sourcePlus','return','fuseA','fuseB','lampPlus','lampMinus'].includes(hit.id)?'meter':'hand';
  if(tool!=='hand'&&!v.prepared176?.has(tool)){this.message('Prepara '+({screwdriver:'el destornillador',wrench:'la llave',meter:'el multímetro'}[tool])+' en la bolsa con Tab.');return false;}
  v.hover=hit.id;const stage=v.state.stage,id=hit.id,probe=v.state.probeColour;v.hand117.engage(hit);v.h.pick(id);v.engageProbe123(id,probe);
  if(/^screw|^bolt/.test(id)&&v.state.toolMotion?.target===id)this.work={id,object:hit.target,stage,kind:'turn',progress:v.state.toolMotion.progress};
  else if((id==='rotateTest'||id==='wheelHub')&&stage===4&&v.state.id==='running'&&!v.state.complete)this.work={id,object:hit.target,stage,kind:'wheel',progress:v.state.rotation/360};
  this.carry();return true;
 }
 end(){this.work=null;this.progress.hidden=true;}
 reset(){this.end();this.release();this.guide.hidden=true;}
 release(){const old=this.carried;this.carried=null;if(old){const job=this.view.motion104?.jobs.get(old.object);if(job)job.qTo.copy(old.localQuaternion);else old.object.quaternion.copy(old.localQuaternion);if(this.view.hand117.contact?.object===old.object)this.view.hand117.hide();}this.leftHand?.hide();}
 carry(){const v=this.view,s=v.state,id=s?.selectedItem;if(!id||v.drag){if(!id)this.release();return;}const o=v.rig?.parts[id];if(!o)return;if(this.carried?.object!==o){this.release();o.updateWorldMatrix(true,true);const center=new T.Box3().setFromObject(o).getCenter(new T.Vector3());this.carried={object:o,rig:v.rig,localCenter:o.worldToLocal(center.clone()),localQuaternion:o.quaternion.clone(),scale:o.getWorldScale(new T.Vector3()),relative:v.camera.getWorldQuaternion(new T.Quaternion()).invert().multiply(o.getWorldQuaternion(new T.Quaternion()))};}
  const h=this.carried;if(h.rig!==v.rig){this.release();return;}v.motion104?.jobs.delete(o);v.camera.updateMatrixWorld(true);const q=v.camera.getWorldQuaternion(new T.Quaternion()).multiply(h.relative),point=v.camera.localToWorld(new T.Vector3(.16,-.22,-.45)),position=point.sub(h.localCenter.clone().multiply(h.scale).applyQuaternion(q));o.position.copy(o.parent.worldToLocal(position));o.quaternion.copy(o.parent.getWorldQuaternion(new T.Quaternion()).invert()).multiply(q);o.updateWorldMatrix(true,true);let b=new T.Box3().setFromObject(o),floor=v.walk176.floor190()+.035;if(b.min.y<floor){const p=o.getWorldPosition(new T.Vector3());p.y+=floor-b.min.y;o.position.copy(o.parent.worldToLocal(p));o.updateWorldMatrix(true,true);b=new T.Box3().setFromObject(o);}
  const center=b.getCenter(new T.Vector3()),right=new T.Vector3(1,0,0).applyQuaternion(v.camera.getWorldQuaternion(new T.Quaternion())),width=Math.min(.20,b.getSize(new T.Vector3()).length()*.25),contact=center.clone().addScaledVector(right,width);
  v.glove.set('carryFilter',true);v.hand117.grasp196(o,o.worldToLocal(contact),'filter');
  if(id==='wheel'||id==='newWheel'||b.getSize(new T.Vector3()).length()>.6){if(!this.leftGlove){this.leftGlove=createGlove104();v.camera.add(this.leftGlove.root);this.leftHand=new InteractionHand117({camera:v.camera,canvas:v.canvas,glove:this.leftGlove,handSide196:-1});this.leftGlove.root.scale.x=-.85;}this.leftGlove.set('carryFilter',true);this.leftHand.grasp196(o,o.worldToLocal(center.clone().addScaledVector(right,-width)),'filter');}else this.leftHand?.hide();
 }
 destination(){const v=this.view,s=v.state,id=targets102(s)[0];if(!id)return null;const tool=/^screw/.test(id)?'screwdriver':/^bolt/.test(id)?'wrench':['sourcePlus','return','fuseA','fuseB','lampPlus','lampMinus'].includes(id)?'meter':'hand';if(tool!=='hand'&&!v.prepared176?.has(tool))return{object:v.bagBrowser157?.model.root,label:'Tab · Preparar '+({screwdriver:'destornillador',wrench:'llave',meter:'multímetro'}[tool])};return{object:actionObject123(v.rig,id,s),label:(s.selectedItem?'E · Colocar en ':(/^screw|^bolt/.test(id)?'Mantén E · ':'E · '))+(LABELS102[id]||id)};}
 guidePoint(){this.guide.hidden=!this.active();if(this.guide.hidden)return;const goal=this.destination();if(!goal?.object){this.guide.hidden=true;return;}const v=this.view,point=new T.Box3().setFromObject(goal.object).getCenter(new T.Vector3());v.camera.updateMatrixWorld(true);const local=v.camera.worldToLocal(point.clone()),p=point.clone().project(v.camera),behind=local.z>=0;let x=p.x,y=-p.y;if(behind){x=-x;y=-y;if(Math.abs(x)+Math.abs(y)<.01)y=1;}const edge=behind||Math.abs(x)>.8||Math.abs(y)>.7;if(edge){const k=Math.max(Math.abs(x)/.8,Math.abs(y)/.7,1);x/=k;y/=k;}this.guide.style.left=(50+x*50)+'%';this.guide.style.top=(50+y*50)+'%';const arrow=this.guide.querySelector('[data-guide189-arrow]');text(arrow,edge?'➤':'◇');arrow.style.transform=edge?'rotate('+Math.atan2(y,x)+'rad)':'none';text(this.guide.querySelector('[data-guide189-label]'),goal.label+' · '+v.camera.position.distanceTo(point).toFixed(1)+' m');}
 update(dt){if(!this.active()){this.end();this.guide.hidden=true;if(!this.view.state?.selectedItem)this.release();return;}this.carry();const v=this.view,w=this.work;if(w){const hit=this.aimed();if(v.state.stage!==w.stage||!hit||hit.id!==w.id||!v.canReach190(hit)){this.end();}else{v.hand117.engage(hit);if(w.kind==='turn')v.h.turn(w.id,Math.min(.05,dt)/.95);else v.h.wheel(v.state.rotation+Math.min(.05,dt)*360/.95);w.progress=w.kind==='turn'?(v.state.toolMotion?.progress||1):v.state.rotation/360;this.progress.value=w.progress;this.progress.hidden=false;if(v.state.complete||v.state.stage!==w.stage||w.kind==='turn'&&!v.state.toolMotion)this.end();}}
  if(this.leftHand?.contact){this.leftGlove.update(dt);this.leftHand.step(performance.now(),!!this.carried);}this.guidePoint();
 }
}
